cd /tmp/lz4exp/stdio-sparse && cat > /tmp/lz4exp/stdio-sparse/holemap.py <<'EOF'
import os,sys
p=sys.argv[1]
f=os.open(p,os.O_RDONLY)
sz=os.fstat(f).st_size
segs=[];pos=0
try:
    while pos<sz:
        try: d=os.lseek(f,pos,os.SEEK_DATA)
        except OSError: segs.append(('HOLE',pos,sz)); break
        if d>pos: segs.append(('HOLE',pos,d))
        try: h=os.lseek(f,d,os.SEEK_HOLE)
        except OSError: h=sz
        segs.append(('DATA',d,h)); pos=h
except Exception as e: print("err",e)
os.close(f)
print(p,"size",sz)
for t,a,b in segs: print("  %-4s %10d .. %10d  (%d)"%(t,a,b,b-a))
EOF
